import { useState } from "react";
import { Card } from "@/shared/ui/data/Card";
import { Stack } from "@/shared/ui/layout/Stack";
import { Row } from "@/shared/ui/layout/Row";
import { Text } from "@/shared/ui/typography/Text";
import { Toggle } from "@/shared/ui/controls/Toggle";

// The real SessionsBehaviorCard renders from a node spec (SESSIONS_BEHAVIOR_SPEC) through the app's
// own KitRenderer (`@/shared/ui/spec`) — app-internal composition infra, unresolvable in this sandbox.
// This vendors the exact layout the spec describes (Card > Stack > [Row(Text, Toggle), note] x2) as
// plain JSX with local state standing in for the real store-bound `autoResumeClaude`/`autoAdvanceOnReply`.

function ToggleRow({ label, on, onToggle }) {
  return (
    <Row gap={8} justify="between">
      <Text>{label}</Text>
      <Toggle on={on} onClick={onToggle} role="switch" ariaChecked={on} />
    </Row>
  );
}
function Note({ children }) {
  return <Text tone="dim" size="sm">{children}</Text>;
}

export function SessionsBehaviorCard() {
  const [autoResumeClaude, setAutoResumeClaude] = useState(true);
  const [autoAdvanceOnReply, setAutoAdvanceOnReply] = useState(true);

  return (
    <Card title="Sessions & console behavior">
      <Stack gap={8}>
        <ToggleRow label="Auto-resume Claude on restart" on={autoResumeClaude} onToggle={() => setAutoResumeClaude((v) => !v)} />
        <Note>
          Panes that had Claude running at last shutdown relaunch it with --continue when the app reopens, restoring the prior conversation. Off means panes start at a bare bash prompt; you'd type claude yourself.
        </Note>
        <ToggleRow label="Cycle to next console on reply" on={autoAdvanceOnReply} onToggle={() => setAutoAdvanceOnReply((v) => !v)} />
        <Note>
          When you send a response to a console, jump focus to the next one waiting in the queue (Ctrl+Shift+N cycles manually). Works while maximized.
        </Note>
      </Stack>
    </Card>
  );
}
